// ══════════════════════════════════════
// SVG 1 — ENGINE ROOM COMMUNICATIONS
// ══════════════════════════════════════
function EngineRoomCommSVG({ lang }) {
  const [step, setStep] = useState(0);

  const exchanges = [
    { from:"BRIDGE", color:C.blue2, icon:"🗺️",
      smcp:"Engine room, this is the bridge. Stand by for manoeuvring. We are approaching the pilot boarding ground. ETA 20 minutes.",
      tr:{fr:"Salle des machines, ici la passerelle. Prêt à manœuvrer. Nous approchons du lieu d'embarquement du pilote. ETA 20 minutes.",es:"Sala de máquinas, aquí el puente. Listos para maniobrar. Nos aproximamos al lugar de embarque del práctico. ETA 20 minutos.",pt:"Casa das máquinas, aqui a ponte. Prontos para manobrar. Estamos a aproximar-nos do local de embarque do prático. ETA 20 minutos."},
      note:{fr:"COMMUNICATION PASSERELLE → S.DES MACHINES\n\n'Stand by for manoeuvring' = se tenir prêt à manœuvrer\n\nPHRASES CLÉS :\n'Stand by main engine' = préparer le moteur principal\n'ETA [X] minutes' = heure d'arrivée estimée\n\nRÉPONSE ATTENDUE :\n'Bridge, engine room. Ready for manoeuvring.\nMain engine is on stand by. Over.'",
            en:"BRIDGE → ENGINE ROOM COMMUNICATION\n\n'Stand by for manoeuvring' = be ready to manoeuvre\n\nKEY PHRASES:\n'Stand by main engine' = prepare main engine\n'ETA [X] minutes' = estimated arrival time\n\nEXPECTED RESPONSE:\n'Bridge, engine room. Ready for manoeuvring.\nMain engine is on stand by. Over.'",
            es:"COMUNICACIÓN PUENTE → SALA DE MÁQUINAS\n\n'Stand by for manoeuvring' = estar listo para maniobrar\n\nRESPUESTA ESPERADA:\n'Bridge, engine room. Ready for manoeuvring.\nMain engine is on stand by. Over.'",
            pt:"COMUNICAÇÃO PONTE → CASA DAS MÁQUINAS\n\n'Stand by for manoeuvring' = estar pronto para manobrar\n\nRESPOSTA ESPERADA:\n'Bridge, engine room. Ready for manoeuvring.\nMain engine is on stand by. Over.'"} },
    { from:"ENGINE ROOM", color:C.eng, icon:"⚙️",
      smcp:"Bridge, engine room. Main engine is ready. Fuel changeover to diesel is complete. Auxiliary blowers are running. Ready for manoeuvring. Over.",
      tr:{fr:"Passerelle, salle des machines. Moteur principal prêt. Changement de combustible vers diesel terminé. Soufflantes auxiliaires en marche. Prêt à manœuvrer. Terminé.",es:"Puente, sala de máquinas. Motor principal listo. Cambio de combustible a diésel completado. Sopladores auxiliares en marcha. Listos para maniobrar. Cambio.",pt:"Ponte, casa das máquinas. Motor principal pronto. Mudança de combustível para diesel concluída. Sopradores auxiliares em funcionamento. Prontos para manobrar. Câmbio."},
      note:{fr:"RAPPORT PRÊT À MANŒUVRER\n\nÉLÉMENTS CLÉS DU RAPPORT :\n→ Main engine is ready (moteur principal prêt)\n→ Fuel changeover complete (dans les ports : diesel obligatoire)\n→ Auxiliary blowers running (ventilation cylindres)\n→ Ready for manoeuvring (disponible)\n\nFUEL CHANGEOVER (obligatoire dans les ECA) :\n'Fuel changeover from heavy fuel oil to marine gas oil is complete at position [lat/long].'\n\nECA = Emission Control Area\n(Manche, Mer du Nord, Mer Baltique, côtes US)",
            en:"READY FOR MANOEUVRING REPORT\n\nKEY REPORT ELEMENTS:\n→ Main engine is ready\n→ Fuel changeover complete (diesel mandatory in ports)\n→ Auxiliary blowers running (cylinder ventilation)\n→ Ready for manoeuvring\n\nFUEL CHANGEOVER (mandatory in ECAs):\n'Fuel changeover from heavy fuel oil to marine gas oil is complete at position [lat/long].'\n\nECA = Emission Control Area\n(English Channel, North Sea, Baltic, US coasts)",
            es:"INFORME LISTO PARA MANIOBRAR\n\nELEMENTOS CLAVE DEL INFORME:\n→ Main engine is ready\n→ Cambio de combustible completado\n→ Soplantes auxiliares en marcha\n→ Ready for manoeuvring\n\nCAMBIO DE COMBUSTIBLE (obligatorio en ECA):\n'Fuel changeover from HFO to MGO is complete at position [lat/long].'",
            pt:"RELATÓRIO PRONTO PARA MANOBRAR\n\nELEMENTOS CHAVE DO RELATÓRIO:\n→ Main engine is ready\n→ Mudança de combustível completa\n→ Sopradores auxiliares em funcionamento\n→ Ready for manoeuvring\n\nMUDANÇA DE COMBUSTÍVEL (obrigatória em ECAs):\n'Fuel changeover from HFO to MGO is complete at position [lat/long].'"} },
    { from:"BRIDGE", color:C.blue2, icon:"🗺️",
      smcp:"Engine room, this is bridge. Dead slow ahead please.",
      tr:{fr:"Salle des machines, ici passerelle. Très petite vitesse avant, s'il vous plaît.",es:"Sala de máquinas, aquí puente. Muy poca velocidad avante, por favor.",pt:"Casa das máquinas, aqui ponte. Muito pouca velocidade avante, por favor."},
      note:{fr:"ORDRES DE VITESSE (Bridge → Engine Room)\n\nSÉQUENCE COMPLÈTE :\nFull ahead · Half ahead · Slow ahead · Dead slow ahead\nStop · Dead slow astern · Slow astern · Half astern · Full astern\n\nCONFIRMATION OBLIGATOIRE :\nChaque ordre doit être confirmé par la S.D.M. :\n'Dead slow ahead — engine on dead slow ahead. RPM [X]. Over.'\n\nRPM (Revolutions Per Minute) :\nToujours indiquer les RPM en réponse aux ordres",
            en:"SPEED ORDERS (Bridge → Engine Room)\n\nFULL SEQUENCE:\nFull ahead · Half ahead · Slow ahead · Dead slow ahead\nStop · Dead slow astern · Slow astern · Half astern · Full astern\n\nMANDATORY CONFIRMATION:\nEach order must be confirmed by ER:\n'Dead slow ahead — engine on dead slow ahead. RPM [X]. Over.'\n\nRPM (Revolutions Per Minute):\nAlways state RPM in response to orders",
            es:"ÓRDENES DE VELOCIDAD (Puente → Sala de Máquinas)\n\nSECUENCIA COMPLETA:\nFull ahead · Half ahead · Slow ahead · Dead slow ahead\nStop · Dead slow astern · Slow astern · Half astern · Full astern\n\nCONFIRMACIÓN OBLIGATORIA:\nCada orden debe ser confirmada por la S.D.M.:\n'Dead slow ahead — engine on dead slow ahead. RPM [X]. Over.'",
            pt:"ORDENS DE VELOCIDADE (Ponte → Sala de Máquinas)\n\nSEQUÊNCIA COMPLETA:\nFull ahead · Half ahead · Slow ahead · Dead slow ahead\nStop · Dead slow astern · Slow astern · Half astern · Full astern\n\nCONFIRMAÇÃO OBRIGATÓRIA:\nCada ordem deve ser confirmada pela S.M.:\n'Dead slow ahead — engine on dead slow ahead. RPM [X]. Over.'"} },
    { from:"ENGINE ROOM", color:C.eng, icon:"⚙️",
      smcp:"Bridge, engine room. I have an engine alarm. High temperature alarm on cylinder number 4. I am investigating. Speed may need to be reduced. Over.",
      tr:{fr:"Passerelle, salle des machines. J'ai une alarme moteur. Alarme haute température sur le cylindre numéro 4. J'enquête. La vitesse devra peut-être être réduite. Terminé.",es:"Puente, sala de máquinas. Tengo una alarma de motor. Alarma de alta temperatura en el cilindro número 4. Estoy investigando. Puede que sea necesario reducir la velocidad. Cambio.",pt:"Ponte, casa das máquinas. Tenho um alarme de motor. Alarme de alta temperatura no cilindro número 4. Estou a investigar. A velocidade pode precisar de ser reduzida. Câmbio."},
      note:{fr:"RAPPORT D'ALARME MOTEUR\n\nSTRUCTURE DU RAPPORT :\n1. Nature de l'alarme (high temp / low pressure / vibration)\n2. Composant affecté (cylinder / bearing / turbocharger)\n3. Action en cours (investigating / repairing)\n4. Impact probable sur la navigation\n\nALARMES COURANTES :\n→ High temperature alarm (alarme haute temp)\n→ Low oil pressure alarm (alarme basse pression huile)\n→ Turbocharger fault (défaut turbo)\n→ Overspeed alarm (alarme survitesse)\n→ Scavenge fire (incendie boite à balayage)",
            en:"ENGINE ALARM REPORT\n\nREPORT STRUCTURE:\n1. Alarm type (high temp / low pressure / vibration)\n2. Affected component (cylinder / bearing / turbocharger)\n3. Action taken (investigating / repairing)\n4. Probable impact on navigation\n\nCOMMON ALARMS:\n→ High temperature alarm\n→ Low oil pressure alarm\n→ Turbocharger fault\n→ Overspeed alarm\n→ Scavenge fire",
            es:"INFORME DE ALARMA DE MOTOR\n\nESTRUCTURA DEL INFORME:\n1. Tipo de alarma (alta temp / baja presión / vibración)\n2. Componente afectado (cilindro / cojinete / turbocompresor)\n3. Acción tomada (investigando / reparando)\n4. Impacto probable en la navegación\n\nALARMAS COMUNES:\n→ Alarma de alta temperatura\n→ Alarma de baja presión de aceite\n→ Fallo del turbocompresor",
            pt:"RELATÓRIO DE ALARME DE MOTOR\n\nESTRUTURA DO RELATÓRIO:\n1. Tipo de alarme (alta temp / baixa pressão / vibração)\n2. Componente afetado (cilindro / rolamento / turbocompressor)\n3. Ação tomada (a investigar / a reparar)\n4. Impacto provável na navegação\n\nALARMES COMUNS:\n→ Alarme de alta temperatura\n→ Alarme de baixa pressão de óleo\n→ Falha do turbocompressor"} },
    { from:"BRIDGE", color:C.blue2, icon:"🗺️",
      smcp:"Engine room, bridge. Understood. Please keep me informed. Can you maintain present speed? Over.",
      tr:{fr:"Salle des machines, passerelle. Bien reçu. Veuillez me tenir informé. Pouvez-vous maintenir la vitesse actuelle ? Terminé.",es:"Sala de máquinas, puente. Recibido. Por favor manténganme informado. ¿Pueden mantener la velocidad actual? Cambio.",pt:"Casa das máquinas, ponte. Bem recebido. Por favor mantenham-me informado. Conseguem manter a velocidade atual? Câmbio."},
      note:{fr:"SUIVI D'ALARME — COMMUNICATION CONTINUE\n\nPHRASES UTILES :\n'Please keep me informed' = tenez-moi informé\n'Can you maintain speed?' = pouvez-vous maintenir la vitesse ?\n'How long will repairs take?' = combien de temps prendra la réparation ?\n'Do you need to stop the engine?' = faut-il arrêter le moteur ?\n\nRÉPONSES ER POSSIBLES :\n'We can maintain present speed for [X] hours.'\n'We need to reduce speed to [X] knots.'\n'We need to stop the engine for [X] minutes.'\n'Repairs are complete. Full power is available.'",
            en:"ALARM FOLLOW-UP — CONTINUOUS COMMUNICATION\n\nUSEFUL PHRASES:\n'Please keep me informed' = update me regularly\n'Can you maintain speed?' = can current speed continue?\n'How long will repairs take?' = ETA for fix?\n'Do you need to stop the engine?' = full stop required?\n\nPOSSIBLE ER RESPONSES:\n'We can maintain present speed for [X] hours.'\n'We need to reduce speed to [X] knots.'\n'We need to stop the engine for [X] minutes.'\n'Repairs are complete. Full power is available.'",
            es:"SEGUIMIENTO DE ALARMA — COMUNICACIÓN CONTINUA\n\nFRASES ÚTILES:\n'Please keep me informed' = manténgame informado\n'Can you maintain speed?' = ¿puede mantener la velocidad actual?\n'How long will repairs take?' = ¿cuánto tardarán las reparaciones?\n'Do you need to stop the engine?' = ¿necesita parar el motor?",
            pt:"ACOMPANHAMENTO DE ALARME — COMUNICAÇÃO CONTÍNUA\n\nFRASES ÚTEIS:\n'Please keep me informed' = mantenha-me informado\n'Can you maintain speed?' = consegue manter a velocidade atual?\n'How long will repairs take?' = quanto tempo levarão as reparações?\n'Do you need to stop the engine?' = precisa de parar o motor?"} },
  ];

  const e = exchanges[step];
  const isBridge = e.from === "BRIDGE";

  return (
    <div>
      <div style={{display:"flex",gap:4,marginBottom:10}}>
        {exchanges.map((_,i)=>(
          <div key={i} onClick={()=>setStep(i)} style={{
            flex:1,height:4,borderRadius:4,cursor:"pointer",
            background:i<=step?(i===step?C.eng:`${C.eng}55`):"rgba(255,255,255,0.1)"}}/>
        ))}
      </div>
      <div style={{fontSize:9,color:C.eng,letterSpacing:2,textAlign:"center",marginBottom:8,fontFamily:"'Cinzel',serif"}}>
        BRIDGE ↔ ENGINE ROOM — {step+1}/{exchanges.length}
      </div>
      <div style={{padding:"12px",borderRadius:14,marginBottom:10,
        background:isBridge?"rgba(77,166,255,0.08)":"rgba(249,115,22,0.08)",
        border:`2px solid ${isBridge?C.blue2:C.eng}55`,animation:"fadeUp 0.3s ease"}}>
        <div style={{fontSize:9,fontWeight:700,color:isBridge?C.blue2:C.eng,marginBottom:6,letterSpacing:1}}>
          {e.icon} {e.from}
        </div>
        <div style={{fontFamily:"'Courier New',monospace",fontSize:12,color:C.white,lineHeight:1.6,fontWeight:600,marginBottom:6}}>
          "{e.smcp}"
        </div>
        {lang!=="en"&&<div style={{fontSize:10,color:C.muted,fontStyle:"italic"}}>{e.tr[lang]||e.tr.fr}</div>}
      </div>
      <div style={{padding:"10px 12px",borderRadius:12,background:"rgba(0,0,0,0.3)",border:"1px solid rgba(255,255,255,0.06)",marginBottom:10,fontSize:11,color:C.white,lineHeight:1.6,whiteSpace:"pre-line"}}>
        {e.note[lang]||e.note.en}
      </div>
      <div style={{display:"flex",gap:8}}>
        <button onClick={()=>setStep(s=>Math.max(0,s-1))} disabled={step===0}
          style={{flex:1,padding:"9px",borderRadius:10,background:"rgba(255,255,255,0.05)",border:"1px solid rgba(255,255,255,0.08)",color:step===0?C.muted:C.white,cursor:step===0?"default":"pointer",fontSize:11}}>
          ◀ {lang==="fr"?"Précédent":lang==="en"?"Previous":lang==="es"?"Anterior":"Anterior"}
        </button>
        <button onClick={()=>setStep(s=>Math.min(exchanges.length-1,s+1))} disabled={step===exchanges.length-1}
          style={{flex:1,padding:"9px",borderRadius:10,background:step===exchanges.length-1?"rgba(255,255,255,0.05)":`${C.eng}22`,border:`1px solid ${step===exchanges.length-1?"rgba(255,255,255,0.08)":C.eng}`,color:C.white,cursor:step===exchanges.length-1?"default":"pointer",fontSize:11,fontWeight:700}}>
          {lang==="fr"?"Suivant":lang==="en"?"Next":lang==="es"?"Siguiente":"Seguinte"} ▶
        </button>
      </div>
    </div>
  );
}

// ══════════════════════════════════════
// SVG 2 — ENGINE DEFECTS FLASHCARDS
// ══════════════════════════════════════
function EngineDefectsFlashcardsSVG({ lang }) {
  const [cat, setCat] = useState("main");
  const [idx, setIdx] = useState(0);
  const [flipped, setFlipped] = useState(false);

  const categories = {
    main:{ label:{fr:"Moteur principal",en:"Main engine",es:"Motor principal",pt:"Motor principal"}, icon:"⚙️", color:C.eng, cards:[
      { q:"How do you report a main engine failure?", a:"I have a main engine failure. Engine has [stopped / reduced power]. Cause is [unknown / fuel / cooling / mechanical]. I am [investigating / unable to proceed]. I require [tug / assistance / time to repair].", tr:{fr:"J'ai une panne de moteur principal. Le moteur s'est [arrêté / réduit en puissance]. Cause [inconnue / carburant / refroidissement / mécanique]. Je [enquête / ne peux pas avancer]. J'ai besoin [d'un remorqueur / assistance / de temps pour réparer].",es:"Tengo una avería del motor principal. El motor se ha [detenido / reducido de potencia]. Causa [desconocida / combustible / refrigeración / mecánica]. Estoy [investigando / no puedo avanzar]. Necesito [un remolcador / asistencia / tiempo para reparar].",pt:"Tenho uma avaria no motor principal. O motor [parou / reduziu de potência]. Causa [desconhecida / combustível / arrefecimento / mecânica]. Estou [a investigar / incapaz de avançar]. Preciso de [um rebocador / assistência / tempo para reparar]."} },
      { q:"How do you report a turbocharger failure?", a:"I have a turbocharger failure on [port/starboard] turbocharger. Engine power is reduced to [X] percent. Maximum speed is now [X] knots. Repairs are [in progress / expected to take X hours].", tr:{fr:"J'ai une panne du turbocompresseur [bâbord/tribord]. La puissance du moteur est réduite à [X] pour cent. La vitesse maximale est maintenant de [X] nœuds. Les réparations sont [en cours / prévues pour durer X heures].",es:"Tengo una avería del turbocompresor [babor/estribor]. La potencia del motor está reducida al [X] por ciento. La velocidad máxima es ahora de [X] nudos. Las reparaciones están [en curso / previstas para durar X horas].",pt:"Tenho uma avaria no turbocompressor [bombordo/estibordo]. A potência do motor está reduzida a [X] por cento. A velocidade máxima é agora de [X] nós. As reparações estão [em curso / previstas para durar X horas]."} },
      { q:"How do you report a main engine bearing failure?", a:"I have a bearing failure on main engine. Engine has been stopped to prevent further damage. I am unable to proceed under own power. I require tug assistance.", tr:{fr:"J'ai une panne de palier sur le moteur principal. Le moteur a été arrêté pour éviter d'autres dommages. Je ne peux pas avancer sous ma propre propulsion. J'ai besoin d'assistance de remorqueur.",es:"Tengo una avería de cojinete en el motor principal. El motor ha sido parado para evitar más daños. No puedo avanzar con propulsión propia. Necesito asistencia de remolcador.",pt:"Tenho uma avaria de chumaceira no motor principal. O motor foi parado para evitar mais danos. Não consigo avançar com propulsão própria. Preciso de assistência de rebocador."} },
      { q:"How do you report a main engine overspeed?", a:"Main engine overspeed alarm has activated. Engine has automatically shut down. I am investigating the cause. Navigation is affected. I am at anchor / drifting.", tr:{fr:"L'alarme de survitesse du moteur principal s'est déclenchée. Le moteur s'est arrêté automatiquement. J'enquête sur la cause. La navigation est affectée. Je suis au mouillage / à la dérive.",es:"La alarma de sobrevelocidad del motor principal se ha activado. El motor se ha detenido automáticamente. Estoy investigando la causa. La navegación está afectada. Estoy fondeado / a la deriva.",pt:"O alarme de sobrevelocidade do motor principal disparou. O motor parou automaticamente. Estou a investigar a causa. A navegação está afetada. Estou fundeado / à deriva."} },
    ]},
    aux:{ label:{fr:"Auxiliaires",en:"Auxiliaries",es:"Auxiliares",pt:"Auxiliares"}, icon:"🔋", color:C.maint, cards:[
      { q:"How do you report a generator failure?", a:"I have a generator failure. Generator [X] has tripped/stopped. We are operating on [X] generators. Load shedding is in effect. Non-essential equipment has been switched off.", tr:{fr:"J'ai une panne de générateur. Le générateur [X] s'est déclenché/arrêté. Nous fonctionnons sur [X] générateurs. Le délestage est en vigueur. Les équipements non essentiels ont été éteints.",es:"Tengo una avería de generador. El generador [X] se ha disparado/parado. Estamos funcionando con [X] generadores. La deslastre de carga está en vigor. Los equipos no esenciales han sido apagados.",pt:"Tenho uma avaria de gerador. O gerador [X] disparou/parou. Estamos a funcionar com [X] geradores. O corte de carga está em vigor. Os equipamentos não essenciais foram desligados."} },
      { q:"How do you report a steering gear failure?", a:"I have a steering gear failure. I have [lost steering / reduced steering]. I am [switching to emergency steering / hand steering / requesting tug]. Vessel is [drifting / at anchor / proceeding at reduced speed].", tr:{fr:"J'ai une panne d'appareil à gouverner. J'ai [perdu la gouverne / gouverne réduite]. Je [passe à la gouverne d'urgence / gouverne manuelle / demande remorqueur]. Le navire est [à la dérive / au mouillage / avance à vitesse réduite].",es:"Tengo una avería del aparato de gobierno. He [perdido el gobierno / gobierno reducido]. Estoy [cambiando al gobierno de emergencia / gobierno manual / solicitando remolcador]. El buque está [a la deriva / fondeado / avanzando a velocidad reducida].",pt:"Tenho uma avaria no aparelho de governo. [Perdi o governo / governo reduzido]. Estou a [mudar para o governo de emergência / governo manual / solicitar rebocador]. O navio está [à deriva / fundeado / a avançar a velocidade reduzida]."} },
      { q:"How do you report a bilge pump failure?", a:"I have a bilge pump failure. Bilge pump [X] is not functioning. Water level in [hold/engine room/bilge] is [rising / stable]. I require [repair / portable pump / assistance].", tr:{fr:"J'ai une panne de pompe de cale. La pompe de cale [X] ne fonctionne pas. Le niveau d'eau dans [la cale/la salle des machines/le puisard] est [en hausse / stable]. J'ai besoin [de réparation / d'une pompe portable / d'assistance].",es:"Tengo una avería de bomba de achique. La bomba de achique [X] no funciona. El nivel de agua en [la bodega/la sala de máquinas/la sentina] está [subiendo / estable]. Necesito [reparación / una bomba portátil / asistencia].",pt:"Tenho uma avaria na bomba de porão. A bomba de porão [X] não está a funcionar. O nível de água em [o porão/a casa das máquinas/o porão de sentina] está [a subir / estável]. Preciso de [reparação / uma bomba portátil / assistência]."} },
      { q:"How do you report a boiler failure?", a:"I have a boiler failure. Boiler [X] has been shut down. Steam pressure is [X] bar and [rising/falling]. Heating of cargo/fuel oil is affected. Estimated repair time is [X] hours.", tr:{fr:"J'ai une panne de chaudière. La chaudière [X] a été arrêtée. La pression de vapeur est de [X] bars et [en hausse/en baisse]. Le chauffage de la cargaison/du fioul est affecté. Durée de réparation estimée : [X] heures.",es:"Tengo una avería de caldera. La caldera [X] ha sido parada. La presión de vapor es de [X] bares y [subiendo/bajando]. La calefacción de la carga/del fuelóleo está afectada. Tiempo estimado de reparación: [X] horas.",pt:"Tenho uma avaria de caldeira. A caldeira [X] foi desligada. A pressão de vapor é de [X] bar e [a subir/a descer]. O aquecimento da carga/do fuelóleo está afetado. Tempo estimado de reparação: [X] horas."} },
    ]},
    fuel:{ label:{fr:"Carburant & Huile",en:"Fuel & Oil",es:"Combustible y Aceite",pt:"Combustível e Óleo"}, icon:"🛢️", color:C.fuel, cards:[
      { q:"How do you report a fuel oil leak?", a:"I have a fuel oil leak in the engine room. Estimated leak rate is [X] litres per hour. I have contained the leak with [drip trays / rags]. I am [repairing / stopping the fuel supply].", tr:{fr:"J'ai une fuite de fioul dans la salle des machines. Taux de fuite estimé : [X] litres par heure. J'ai contenu la fuite avec [bacs de rétention / chiffons]. Je suis en train [de réparer / de couper l'alimentation en carburant].",es:"Tengo una fuga de fuelóleo en la sala de máquinas. Ritmo de fuga estimado: [X] litros por hora. He contenido la fuga con [bandejas de retención / trapos]. Estoy [reparando / cortando el suministro de combustible].",pt:"Tenho uma fuga de fuelóleo na casa das máquinas. Ritmo de fuga estimado: [X] litros por hora. Contive a fuga com [tabuleiros de retenção / panos]. Estou a [reparar / cortar o fornecimento de combustível]."} },
      { q:"How do you report low lubricating oil pressure?", a:"I have low lubricating oil pressure alarm on main engine. Oil pressure is [X] bar. Normal pressure is [X] bar. I am investigating. Engine speed has been reduced as a precaution.", tr:{fr:"J'ai une alarme de basse pression d'huile de lubrification sur le moteur principal. La pression d'huile est de [X] bars. La pression normale est de [X] bars. J'enquête. La vitesse du moteur a été réduite par précaution.",es:"Tengo una alarma de baja presión de aceite lubricante en el motor principal. La presión de aceite es de [X] bares. La presión normal es de [X] bares. Estoy investigando. La velocidad del motor se ha reducido por precaución.",pt:"Tenho um alarme de baixa pressão de óleo lubrificante no motor principal. A pressão de óleo é de [X] bar. A pressão normal é de [X] bar. Estou a investigar. A velocidade do motor foi reduzida por precaução."} },
      { q:"How do you report fuel changeover?", a:"Fuel changeover from [heavy fuel oil / diesel] to [diesel / heavy fuel oil] commenced at [time] UTC at position [lat/long]. Changeover is complete. Fuel oil viscosity is [X] centistokes.", tr:{fr:"Le changement de carburant du [fioul lourd / diesel] vers le [diesel / fioul lourd] a commencé à [heure] UTC en position [lat/long]. Le changement est terminé. La viscosité du fioul est de [X] centistokes.",es:"El cambio de combustible de [fuelóleo pesado / diésel] a [diésel / fuelóleo pesado] comenzó a las [hora] UTC en la posición [lat/long]. El cambio está completado. La viscosidad del fuelóleo es de [X] centistokes.",pt:"A mudança de combustível de [fuelóleo pesado / diesel] para [diesel / fuelóleo pesado] começou às [hora] UTC na posição [lat/long]. A mudança está concluída. A viscosidade do fuelóleo é de [X] centistokes."} },
      { q:"How do you report a fuel contamination?", a:"I have fuel contamination in tank [X]. The fuel is [contaminated with water / mixed with wrong grade]. I have isolated the affected tank. I require fuel analysis / alternative fuel supply.", tr:{fr:"J'ai une contamination de carburant dans la citerne [X]. Le carburant est [contaminé par de l'eau / mélangé avec une qualité incorrecte]. J'ai isolé la citerne affectée. J'ai besoin d'une analyse de carburant / d'une alimentation en carburant alternative.",es:"Tengo una contaminación de combustible en el tanque [X]. El combustible está [contaminado con agua / mezclado con un grado incorrecto]. He aislado el tanque afectado. Necesito un análisis de combustible / un suministro de combustible alternativo.",pt:"Tenho uma contaminação de combustível no tanque [X]. O combustível está [contaminado com água / misturado com um grau incorreto]. Isolei o tanque afetado. Preciso de uma análise de combustível / um fornecimento de combustível alternativo."} },
    ]},
    alarm:{ label:{fr:"Alarmes & Urgences",en:"Alarms & Emergencies",es:"Alarmas y Emergencias",pt:"Alarmes e Emergências"}, icon:"🚨", color:C.alarm, cards:[
      { q:"How do you report a scavenge fire?", a:"I have a scavenge fire on cylinder [X]. Engine speed has been reduced. Scavenge drain cocks are open. I am monitoring the situation. [Fire is extinguished / Fire continues].", tr:{fr:"J'ai un incendie en boite à balayage sur le cylindre [X]. La vitesse du moteur a été réduite. Les robinets de vidange du balayage sont ouverts. Je surveille la situation. [L'incendie est éteint / L'incendie continue].",es:"Tengo un incendio en la caja de barrido en el cilindro [X]. La velocidad del motor se ha reducido. Los grifos de purga de barrido están abiertos. Estoy vigilando la situación. [El incendio está apagado / El incendio continúa].",pt:"Tenho um incêndio na caixa de varredura no cilindro [X]. A velocidade do motor foi reduzida. As torneiras de drenagem da varredura estão abertas. Estou a monitorizar a situação. [O incêndio está apagado / O incêndio continua]."} },
      { q:"How do you report flooding in the engine room?", a:"I have flooding in the engine room. Water is entering from [bilge / sea valve / pipe failure]. Rate of flooding is [slow/fast]. Bilge pumps are [running / not sufficient]. I may require assistance.", tr:{fr:"J'ai un envahissement dans la salle des machines. L'eau entre par [le puisard / la vanne de mer / une rupture de tuyauterie]. Le taux d'envahissement est [lent/rapide]. Les pompes de cale sont [en marche / insuffisantes]. Je pourrais avoir besoin d'assistance.",es:"Tengo una inundación en la sala de máquinas. El agua entra por [la sentina / la válvula de mar / una rotura de tubería]. El ritmo de inundación es [lento/rápido]. Las bombas de achique están [en marcha / insuficientes]. Podría necesitar asistencia.",pt:"Tenho um alagamento na casa das máquinas. A água entra por [o porão de sentina / a válvula de mar / uma rutura de tubagem]. O ritmo de alagamento é [lento/rápido]. As bombas de porão estão [em funcionamento / insuficientes]. Poderei precisar de assistência."} },
      { q:"How do you report loss of electrical power?", a:"I have a blackout. All electrical power has been lost. Emergency generator has [started / failed to start]. Essential services are [restored / still not available]. I am investigating the cause.", tr:{fr:"J'ai un black-out. Toute l'alimentation électrique a été perdue. Le générateur de secours a [démarré / refusé de démarrer]. Les services essentiels sont [rétablis / toujours indisponibles]. J'enquête sur la cause.",es:"Tengo un apagón. Se ha perdido toda la alimentación eléctrica. El generador de emergencia ha [arrancado / no ha arrancado]. Los servicios esenciales están [restablecidos / aún no disponibles]. Estoy investigando la causa.",pt:"Tenho um blackout. Toda a alimentação elétrica foi perdida. O gerador de emergência [arrancou / não arrancou]. Os serviços essenciais estão [restabelecidos / ainda indisponíveis]. Estou a investigar a causa."} },
      { q:"How do you report a CO2 system activation?", a:"CO2 system has been activated in engine room / cargo hold [X]. All personnel have evacuated. Engine room is sealed. I require immediate assistance and ventilation before re-entry.", tr:{fr:"Le système CO2 a été activé dans la salle des machines / la cale [X]. Tout le personnel a évacué. La salle des machines est étanche. J'ai besoin d'assistance immédiate et de ventilation avant la rentrée.",es:"El sistema CO2 ha sido activado en la sala de máquinas / la bodega [X]. Todo el personal ha evacuado. La sala de máquinas está sellada. Necesito asistencia inmediata y ventilación antes de volver a entrar.",pt:"O sistema CO2 foi ativado na casa das máquinas / no porão [X]. Todo o pessoal evacuou. A casa das máquinas está vedada. Preciso de assistência imediata e ventilação antes de reentrar."} },
    ]},
  };

  const c = categories[cat];
  const card = c.cards[idx];

  return (
    <div>
      <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:6,marginBottom:10}}>
        {Object.entries(categories).map(([k,v])=>(
          <button key={k} onClick={()=>{setCat(k);setIdx(0);setFlipped(false);}} style={{
            padding:"7px 4px",borderRadius:10,cursor:"pointer",fontSize:9,fontWeight:700,
            background:cat===k?`${v.color}22`:"rgba(255,255,255,0.04)",
            border:`1.5px solid ${cat===k?v.color:"rgba(255,255,255,0.08)"}`,
            color:cat===k?v.color:C.muted}}>
            {v.icon} {v.label[lang]||v.label.en}
          </button>
        ))}
      </div>
      <div style={{display:"flex",gap:4,marginBottom:10}}>
        {c.cards.map((_,i)=>(
          <div key={i} onClick={()=>{setIdx(i);setFlipped(false);}} style={{
            flex:1,height:4,borderRadius:4,cursor:"pointer",
            background:i===idx?c.color:i<idx?`${c.color}55`:"rgba(255,255,255,0.1)"}}/>
        ))}
      </div>
      <div onClick={()=>setFlipped(f=>!f)} style={{
        padding:"16px",borderRadius:14,cursor:"pointer",minHeight:120,
        background:flipped?`${c.color}18`:"rgba(0,0,0,0.4)",
        border:`2px solid ${flipped?c.color:"rgba(255,255,255,0.08)"}`,
        transition:"all 0.3s ease",animation:"fadeUp 0.3s ease",
        display:"flex",flexDirection:"column",justifyContent:"center",marginBottom:10}}>
        {!flipped?(
          <div>
            <div style={{fontSize:9,color:C.muted,letterSpacing:2,marginBottom:8}}>❓ {lang==="fr"?"Touche pour la réponse SMCP":lang==="en"?"Tap for SMCP answer":lang==="es"?"Toca para respuesta SMCP":"Toque para resposta SMCP"}</div>
            <div style={{fontSize:13,color:C.white,fontWeight:700,lineHeight:1.5}}>{card.q}</div>
          </div>
        ):(
          <div>
            <div style={{fontSize:9,color:c.color,letterSpacing:2,marginBottom:8}}>✅ SMCP ANSWER</div>
            <div style={{fontFamily:"'Courier New',monospace",fontSize:11,color:C.white,lineHeight:1.7,marginBottom:6,whiteSpace:"pre-line"}}>{card.a}</div>
            {lang!=="en"&&<div style={{fontSize:10,color:C.muted,fontStyle:"italic",borderTop:"1px solid rgba(255,255,255,0.06)",paddingTop:6}}>{card.tr[lang]||card.tr.fr}</div>}
          </div>
        )}
      </div>
      <div style={{display:"flex",gap:8}}>
        <button onClick={()=>{setIdx(i=>Math.max(0,i-1));setFlipped(false);}} disabled={idx===0}
          style={{flex:1,padding:"9px",borderRadius:10,background:"rgba(255,255,255,0.05)",border:"1px solid rgba(255,255,255,0.08)",color:idx===0?C.muted:C.white,cursor:idx===0?"default":"pointer",fontSize:11}}>
          ◀ {lang==="fr"?"Précédent":lang==="en"?"Previous":lang==="es"?"Anterior":"Anterior"}
        </button>
        <button onClick={()=>{setIdx(i=>Math.min(c.cards.length-1,i+1));setFlipped(false);}} disabled={idx===c.cards.length-1}
          style={{flex:1,padding:"9px",borderRadius:10,background:idx===c.cards.length-1?"rgba(255,255,255,0.05)":`${c.color}22`,border:`1px solid ${idx===c.cards.length-1?"rgba(255,255,255,0.08)":c.color}`,color:C.white,cursor:idx===c.cards.length-1?"default":"pointer",fontSize:11,fontWeight:700}}>
          {lang==="fr"?"Suivant":lang==="en"?"Next":lang==="es"?"Siguiente":"Seguinte"} ▶
        </button>
      </div>
    </div>
  );
}

